/// Firmware version string (aligned, 16 bytes on wire)
#[derive(Debug, Clone, Default, PartialEq)]
pub struct FirmwareVersion {
    pub version: String,
}

impl FirmwareVersion {
    pub const WIRE_SIZE: usize = 16;

    /// Encode to wire bytes (16 bytes).
    /// Input values are in the agreed `unit`; scale multiplied during bit packing.
    pub fn encode(&self) -> [u8; 16] {
        let mut buf = [0u8; 16];
        let mut offset = 0usize;
        {
            let bytes = self.version.as_bytes();
            let len = bytes.len().min(16);
            buf[offset..offset + len].copy_from_slice(&bytes[..len]);
            // remaining bytes stay zero
            offset += 16;
        }
        let _ = offset; // suppress unused warning
        buf
    }

    /// Decode from wire bytes.
    /// Output values are in the agreed `unit`; scale divided during bit unpacking.
    pub fn decode(buf: &[u8]) -> Option<Self> {
        if buf.len() < 16 {
            return None;
        }
        let mut offset = 0usize;
        let version = {
            let slice = &buf[offset..offset + 16];
            let end = slice.iter().position(|&b| b == 0).unwrap_or(16);
            String::from_utf8_lossy(&slice[..end]).into_owned()
        };
        offset += 16;
        let _ = offset; // suppress unused warning

        Some(Self {
            version,
        })
    }
}

/// Test run command — references uploaded G-code and assigns test data ID (aligned, 14 bytes on wire)
#[derive(Debug, Clone, Default, PartialEq)]
pub struct TestRun {
    pub gcode_id: String,
    pub test_data_id: String,
}

impl TestRun {
    pub const WIRE_SIZE: usize = 14;

    /// Encode to wire bytes (14 bytes).
    /// Input values are in the agreed `unit`; scale multiplied during bit packing.
    pub fn encode(&self) -> [u8; 14] {
        let mut buf = [0u8; 14];
        let mut offset = 0usize;
        {
            let bytes = self.gcode_id.as_bytes();
            let len = bytes.len().min(7);
            buf[offset..offset + len].copy_from_slice(&bytes[..len]);
            // remaining bytes stay zero
            offset += 7;
        }
        {
            let bytes = self.test_data_id.as_bytes();
            let len = bytes.len().min(7);
            buf[offset..offset + len].copy_from_slice(&bytes[..len]);
            // remaining bytes stay zero
            offset += 7;
        }
        let _ = offset; // suppress unused warning
        buf
    }

    /// Decode from wire bytes.
    /// Output values are in the agreed `unit`; scale divided during bit unpacking.
    pub fn decode(buf: &[u8]) -> Option<Self> {
        if buf.len() < 14 {
            return None;
        }
        let mut offset = 0usize;
        let gcode_id = {
            let slice = &buf[offset..offset + 7];
            let end = slice.iter().position(|&b| b == 0).unwrap_or(7);
            String::from_utf8_lossy(&slice[..end]).into_owned()
        };
        offset += 7;
        let test_data_id = {
            let slice = &buf[offset..offset + 7];
            let end = slice.iter().position(|&b| b == 0).unwrap_or(7);
            String::from_utf8_lossy(&slice[..end]).into_owned()
        };
        offset += 7;
        let _ = offset; // suppress unused warning

        Some(Self {
            gcode_id,
            test_data_id,
        })
    }
}

/// Firmware notification message (aligned, 101 bytes on wire)
#[derive(Debug, Clone, Default, PartialEq)]
pub struct Notification {
    pub r#type: NotificationType,
    pub message: String,
}

impl Notification {
    pub const WIRE_SIZE: usize = 101;

    /// Encode to wire bytes (101 bytes).
    /// Input values are in the agreed `unit`; scale multiplied during bit packing.
    pub fn encode(&self) -> [u8; 101] {
        let mut buf = [0u8; 101];
        let mut offset = 0usize;
        buf[offset] = self.r#type.to_wire();
        offset += 1;
        {
            let bytes = self.message.as_bytes();
            let len = bytes.len().min(100);
            buf[offset..offset + len].copy_from_slice(&bytes[..len]);
            // remaining bytes stay zero
            offset += 100;
        }
        let _ = offset; // suppress unused warning
        buf
    }

    /// Decode from wire bytes.
    /// Output values are in the agreed `unit`; scale divided during bit unpacking.
    pub fn decode(buf: &[u8]) -> Option<Self> {
        if buf.len() < 101 {
            return None;
        }
        let mut offset = 0usize;
        let r#type = NotificationType::from_wire(buf[offset]).unwrap_or_default();
        offset += 1;
        let message = {
            let slice = &buf[offset..offset + 100];
            let end = slice.iter().position(|&b| b == 0).unwrap_or(100);
            String::from_utf8_lossy(&slice[..end]).into_owned()
        };
        offset += 100;
        let _ = offset; // suppress unused warning

        Some(Self {
            r#type,
            message,
        })
    }
}

