// ============================================================
// Typed message facade
// ============================================================
// Bridges the generic runtime (raw command id + payload bytes) to typed,
// decoded payloads — the "last mile" so callers don't hand-map ids to structs.

/// A decoded inbound payload (a DATA response or an async notification),
/// tagged with the message it belongs to.
#[derive(Debug, Clone, PartialEq)]
pub enum Inbound {
    /// DATA response for `sample` (command 0).
    Sample(Sample),
    /// DATA response for `state` (command 1).
    State(MachineState),
    /// DATA response for `machine_configuration` (command 2).
    MachineConfiguration(MachineConfiguration),
    /// DATA response for `firmware_version` (command 3).
    FirmwareVersion(FirmwareVersion),
    /// DATA response for `sample_profile` (command 4).
    SampleProfile(SampleProfile),
    /// DATA response for `file_download` (command 9).
    FileDownload(StoredSample),
    /// Async `notification` notification.
    Notification(Notification),
    /// Command not recognized as a DATA producer — raw bytes preserved.
    Unknown { command: u8, payload: Vec<u8> },
}

impl Inbound {
    /// Decode a DATA response for `command` into its typed payload. Unknown
    /// commands and decode failures yield [`Inbound::Unknown`].
    pub fn decode_data(command: u8, payload: &[u8]) -> Self {
        match command {
            0 => Sample::decode(payload)
                .map(Inbound::Sample)
                .unwrap_or_else(|| Inbound::Unknown { command, payload: payload.to_vec() }),
            1 => MachineState::decode(payload)
                .map(Inbound::State)
                .unwrap_or_else(|| Inbound::Unknown { command, payload: payload.to_vec() }),
            2 => MachineConfiguration::decode(payload)
                .map(Inbound::MachineConfiguration)
                .unwrap_or_else(|| Inbound::Unknown { command, payload: payload.to_vec() }),
            3 => FirmwareVersion::decode(payload)
                .map(Inbound::FirmwareVersion)
                .unwrap_or_else(|| Inbound::Unknown { command, payload: payload.to_vec() }),
            4 => SampleProfile::decode(payload)
                .map(Inbound::SampleProfile)
                .unwrap_or_else(|| Inbound::Unknown { command, payload: payload.to_vec() }),
            9 => StoredSample::decode(payload)
                .map(Inbound::FileDownload)
                .unwrap_or_else(|| Inbound::Unknown { command, payload: payload.to_vec() }),
            _ => Inbound::Unknown { command, payload: payload.to_vec() },
        }
    }

    /// Decode an async `notification` notification payload into its typed struct.
    pub fn decode_notification(payload: &[u8]) -> Option<Notification> {
        Notification::decode(payload)
    }
}

// ============================================================
// Bit Packing Helpers
// ============================================================

/// Write `bits` bits from `value` into `buf` starting at `bit_off`. LSB-first.
fn pack_bits(buf: &mut [u8], bit_off: u32, bits: u32, value: u32) {
    for i in 0..bits {
        let byte_idx = ((bit_off + i) / 8) as usize;
        let bit_idx = (bit_off + i) % 8;
        if (value >> i) & 1 != 0 {
            buf[byte_idx] |= 1 << bit_idx;
        }
    }
}

/// Read `bits` bits from `buf` starting at `bit_off`. LSB-first. Returns unsigned.
fn unpack_bits(buf: &[u8], bit_off: u32, bits: u32) -> u32 {
    let mut value: u32 = 0;
    for i in 0..bits {
        let byte_idx = ((bit_off + i) / 8) as usize;
        let bit_idx = (bit_off + i) % 8;
        if (buf[byte_idx] >> bit_idx) & 1 != 0 {
            value |= 1 << i;
        }
    }
    value
}

