    #[test]
    fn test_g_code_value_remap() {
        assert_eq!(GCode::from_value(0).unwrap(), GCode::RapidMove);
        assert_eq!(GCode::RapidMove.to_value(), 0);
        assert_eq!(GCode::from_value(1).unwrap(), GCode::LinearMove);
        assert_eq!(GCode::LinearMove.to_value(), 1);
        assert_eq!(GCode::from_value(2).unwrap(), GCode::CwArc);
        assert_eq!(GCode::CwArc.to_value(), 2);
        assert_eq!(GCode::from_value(3).unwrap(), GCode::CcwArc);
        assert_eq!(GCode::CcwArc.to_value(), 3);
        assert_eq!(GCode::from_value(4).unwrap(), GCode::Dwell);
        assert_eq!(GCode::Dwell.to_value(), 4);
        assert_eq!(GCode::from_value(28).unwrap(), GCode::Home);
        assert_eq!(GCode::Home.to_value(), 28);
        assert_eq!(GCode::from_value(90).unwrap(), GCode::Absolute);
        assert_eq!(GCode::Absolute.to_value(), 90);
        assert_eq!(GCode::from_value(91).unwrap(), GCode::Incremental);
        assert_eq!(GCode::Incremental.to_value(), 91);
        assert_eq!(GCode::from_value(122).unwrap(), GCode::Stop);
        assert_eq!(GCode::Stop.to_value(), 122);
        assert_eq!(GCode::from_value(123).unwrap(), GCode::Waveform);
        assert_eq!(GCode::Waveform.to_value(), 123);
    }
