    // Typed facade: a DATA response must decode back to the right variant.
    #[test]
    fn test_facade_sample_decode_data() {
        let original = Sample::default();
        let bytes = original.encode();
        match Inbound::decode_data(0, &bytes) {
            Inbound::Sample(v) => assert_eq!(v, original),
            other => panic!("expected Sample, got {:?}", other),
        }
    }
